  const MARK = PAGE;
  const FOLD = 'M36 9V18A2 2 0 0 0 38 20H47Z';
  const ORBIT_BACK = 'M6.42 46.39A28 10.5 -24 0 1 57.58 23.61';
  const ORBIT_FRONT = 'M57.58 23.61A28 10.5 -24 0 1 6.42 46.39';
