    postMessage(data) { setTimeout(() => { try { handler({ data }); } catch (e) { window.__heicPost({ id: data.id, imageDataArr: [], error: String(e) }); } }, 30); },
    addEventListener(t, fn) { if (t === 'message') listeners.push(fn); },
