  if (quality === 'small') k = Math.min(1, 2000 / Math.max(nw, nh));
  if (nw * nh * k * k > 40e6) k = Math.sqrt(40e6 / (nw * nh));
  const w = Math.max(1, Math.round(nw * k)), hh = Math.max(1, Math.round(nh * k));
