  const selBar = h('div', { class: 'ord-selbar' }, selCount, allBtn, noneBtn, invBtn, h('span', { class: 'grow' }), exSel, dupSel, delSel);
  // tastiera: Ctrl+A tutte, Esc nessuna, Canc elimina le selezionate
