      const score = a => { const t = Math.tan(a * Math.PI / 180); const m = new Map(); for (let k = 0; k < pts.length; k += 2) { const c = Math.round(pts[k] - pts[k + 1] * t); m.set(c, (m.get(c) || 0) + 1); } let s = 0; for (const v of m.values()) s += v * v; return s; };
