        url = URL.createObjectURL(new Blob([`const OCRPrep = (${makeOCRPrep.toString()})();\nconst ImgKit = (${makeImgKit.toString()})();\nconst OCRLayout = (${makeOCRLayout.toString()})();\n(${workerMain.toString()})();`], { type: 'text/javascript' }));
