  let multi = { pi: -1, refs: [] }; // 'b:'+chiave del blocco · 'o:'+chiave dell'oggetto · 'i:'+id dell'elemento
  const mRefs = () => multi.pi === viewer.page - 1 ? multi.refs : [];
