    // scansione? (carta non bianca, rumore): uniforma lo sfondo e raddrizza
    let acc = 0, p50 = 255; for (let v = 0; v < 256; v++) { acc += hist[v]; if (acc >= N * 0.5) { p50 = v; break; } }
