      while (grow) { grow = false; for (const o of hsorted) { if (Math.abs(o.y0 - g.y0) > P(1.8)) continue; if (o.x1 >= x0 - P(10) && o.x0 < x0) { x0 = o.x0; grow = true; } if (o.x0 <= x1 + P(10) && o.x1 > x1) { x1 = o.x1; grow = true; } } }
