    const flush = () => { if (cur && cur.runs.some(r => r.text.trim())) blocks.push(cur); cur = null; };
    const BLOCK = /^(P|DIV|H[1-6]|LI|TR|TABLE|UL|OL|BR|BLOCKQUOTE|PRE|SECTION|ARTICLE|HEADER|FOOTER|TBODY|THEAD|DL|DT|DD|HR)$/;
