    rows.push([H('Voce'), H(model.cols[0], { align: 'right' }), H(model.cols[1], { align: 'right' }), H('Variazione', { align: 'right', fill: B.ink2 }), H('Var. %', { align: 'right', fill: B.ink2 })]);
    const heights = [26, 16, 14, 24];
    let longest = 20;
