      const a = Math.atan2(ctx.H, ctx.W), cx = ctx.W / 2 - Math.cos(a) * w / 2 + Math.sin(a) * size / 3, cy = ctx.H / 2 - Math.sin(a) * w / 2 - Math.cos(a) * size / 3;
