      try { const sub = `file360 - ${fill(r.name)} - ${fill('{data}')} ${pad(new Date().getHours())}${pad(new Date().getMinutes())}`; await writeOut(dir, sub, outs); note = `Salvati anche nella cartella «${dir.name}/${sub}». ` + note; }
