    if (!r.ok) { let m = ''; try { m = (await r.clone().json()).error_summary || (await r.json()).error?.message || ''; } catch { } throw new Error(`${P[id].name}: richiesta non riuscita (${r.status}${m ? ' · ' + m : ''})`); }
